window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-e385e96a14da5524"]={"versions": [{"id": "FIG-e385e96a14da5524", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Informelles Prozess- und Datenflussdiagramm zur Erzeugung zielgruppenspezifischer Dokumente im Kontext des AUTOSAR Generic Structure Template (Dokumentationsmodellierung / <code>DocumentViewSelectable</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure/Rollen:</strong></li>\n<li><code>Software Developer</code> (Dokumentationsautor, liefert Sichten)</li>\n<li><code>Autosar Integrator</code> (Dokumentationsverarbeiter, wählt Sichten aus)</li>\n<li><strong>Werkzeuge/Prozessoren:</strong></li>\n<li><code>Document Editor</code>: Werkzeug zur Erstellung und Anreicherung von Dokumentationsinhalten mit Sichten.</li>\n<li><code>Document Processor</code>: Verarbeitungs- und Filterschritt, der aus dem Gesamtmodell zielgruppenspezifische Ausgaben filtert und generiert.</li>\n<li><strong>Artefakte & Datenobjekte:</strong></li>\n<li><code>ARXML Documentation Content Incl. Views</code>: Eingangsdatenmodell in ARXML, das Dokumentationsinhalte mitsamt zugeordneten Sichten (<code>DocumentViewSelectable</code>) bündelt.</li>\n<li><code>Document with view</code> (mit roter Kennzeichnung): Generiertes Zieldokument für <code>audience A</code>.</li>\n<li><code>Document with view</code> (mit grüner Kennzeichnung): Generiertes Zieldokument für <code>audience B</code>.</li>\n<li><strong>Grenzlinie:</strong> Eine gestrichelte gelbe Linie trennt den internen Generierungsprozess von den final publizierten Zieldokumenten.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der <code>Software Developer</code> bedient den <code>Document Editor</code> (<code>provide views</code>) und erzeugt das Artefakt <code>ARXML Documentation Content Incl. Views</code>.</li>\n<li>Das strukturierte Dokumentenartefakt wird dem <code>Document Processor</code> als Eingangsdatenmodell übergeben.</li>\n<li>Der <code>Autosar Integrator</code> instruiert den <code>Document Processor</code> mit der Sichtenauswahl (<code>select view</code>).</li>\n<li>Basierend auf der selektierten Sicht transformiert und filtert der <code>Document Processor</code> die Inhalte und erzeugt zielgruppenspezifische Dokumente:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Document with view dedicated for audience A</code></li>\n<li><code>Document with view dedicated for audience B</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Illustrierende Übersicht zur Wirkungsweise der filterbaren Dokumentationssichten (<code>DocumentViewSelectable</code>) neben Sprachanpassungen (<code>LanguageSpecific</code>) und Stereotyp-Varianten (<code>atpVariation</code>). Werkzeuge müssen in der Lage sein, beim Autorenschritt Dokumentationsobjekte bestimmten View-Identifikatoren zuzuordnen und beim Verarbeitungs-/Generierungsschritt über View-Filterung zielgruppenreine Publikationsdokumente zu erzeugen.</p>"}, {"id": "FIG-548600da1ed76703", "releases": ["R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Informelles Prozess- und Datenflussdiagramm zur Erzeugung zielgruppenspezifischer Dokumente im Kontext des AUTOSAR Generic Structure Template (Dokumentationsmodellierung / <code>DocumentViewSelectable</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure/Rollen:</strong></li>\n<li><code>Software Developer</code> (Dokumentationsautor, liefert Sichten)</li>\n<li><code>Autosar Integrator</code> (Dokumentationsverarbeiter, wählt Sichten aus)</li>\n<li><strong>Werkzeuge/Prozessoren:</strong></li>\n<li><code>Document Editor</code>: Werkzeug zur Erstellung und Anreicherung von Dokumentationsinhalten mit Sichten.</li>\n<li><code>Document Processor</code>: Verarbeitungs- und Filterschritt, der aus dem Gesamtmodell zielgruppenspezifische Ausgaben filtert und generiert.</li>\n<li><strong>Artefakte & Datenobjekte:</strong></li>\n<li><code>ARXML Documentation Content Incl. Views</code>: Eingangsdatenmodell in ARXML, das Dokumentationsinhalte mitsamt zugeordneten Sichten (<code>DocumentViewSelectable</code>) bündelt.</li>\n<li><code>Document with view</code> (mit roter Kennzeichnung): Generiertes Zieldokument für <code>audience A</code>.</li>\n<li><code>Document with view</code> (mit grüner Kennzeichnung): Generiertes Zieldokument für <code>audience B</code>.</li>\n<li><strong>Grenzlinie:</strong> Eine gestrichelte gelbe Linie trennt den internen Generierungsprozess von den final publizierten Zieldokumenten.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der <code>Software Developer</code> bedient den <code>Document Editor</code> (<code>provide views</code>) und erzeugt das Artefakt <code>ARXML Documentation Content Incl. Views</code>.</li>\n<li>Das strukturierte Dokumentenartefakt wird dem <code>Document Processor</code> als Eingangsdatenmodell übergeben.</li>\n<li>Der <code>Autosar Integrator</code> instruiert den <code>Document Processor</code> mit der Sichtenauswahl (<code>select view</code>).</li>\n<li>Basierend auf der selektierten Sicht transformiert und filtert der <code>Document Processor</code> die Inhalte und erzeugt zielgruppenspezifische Dokumente:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Document with view dedicated for audience A</code></li>\n<li><code>Document with view dedicated for audience B</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Illustrierende Übersicht zur Wirkungsweise der filterbaren Dokumentationssichten (<code>DocumentViewSelectable</code>) neben Sprachanpassungen (<code>LanguageSpecific</code>) und Stereotyp-Varianten (<code>atpVariation</code>). Werkzeuge müssen in der Lage sein, beim Autorenschritt Dokumentationsobjekte bestimmten View-Identifikatoren zuzuordnen und beim Verarbeitungs-/Generierungsschritt über View-Filterung zielgruppenreine Publikationsdokumente zu erzeugen.</p>"}], "trans": [{"from": "FIG-e385e96a14da5524", "to": "FIG-548600da1ed76703", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
